116→export function getApiClientConfig(): ApiClientConfig {
117→  if (!_config) throw new Error('API client not configured. Call setApiClientConfig() first.');
118→  return _config;
119→}
120→
121→function getCachedInstance(): AxiosInstance {
122→  if (!_instance) {
123→    _instance = createAxiosInstance(getApiClientConfig());
124→  }
125→  return _instance;
126→}
