128→export const customInstance = async <T>(
129→  config: AxiosRequestConfig,
130→  options?: AxiosRequestConfig & { _axiosInstance?: AxiosInstance }
131→): Promise<T> => {
132→  const { _axiosInstance, ...restOptions } = options ?? {};
133→
134→  if (_axiosInstance) {
135→    // Instance-scoped path: the provided instance has its own interceptors for auth
136→    const response = await _axiosInstance.request<T>({
137→      ...config,
138→      ...restOptions,
139→      headers: {
140→        ...config.headers,
141→        ...restOptions.headers,
142→      },
143→    });
144→    return response.data;
145→  }
146→
147→  // Singleton path: uses getCachedInstance() which has its own request interceptor
148→  const instance = getCachedInstance();
149→
150→  const response = await instance.request<T>({
151→    ...config,
152→    ...restOptions,
153→    headers: {
154→      ...config.headers,
155→      ...restOptions.headers,
156→    },
157→  });
158→
159→  return response.data;
160→};
161→
162→export default customInstance;
163→
164→export type ErrorType<Error> = AxiosError<Error>;
165→export type BodyType<BodyData> = BodyData;
166→
